mapper.select:
SELECT id, username, password, status, role, create_time, update_time
FROM account
WHERE username = #{username}

SELECT id, username, password, status, role, create_time, update_time
FROM account
WHERE id = #{id}

mapper.update:
UPDATE account
SET password = #{password}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT a.id, a.username, COUNT(w.id) AS workCount
FROM account a LEFT JOIN work w ON a.id = w.owner_id AND w.audit_status='APPROVED'
WHERE a.role='USER' GROUP BY a.id ORDER BY workCount DESC LIMIT #{limit}
